#include <stdio.h>
#include <libvmi/libvmi.h>

static void try_config(const char *label, const char *config)
{
    vmi_instance_t vmi = NULL;
    vmi_init_error_t error = VMI_INIT_ERROR_NONE;
    vmi_init_complete(&vmi, (void *)"/tmp/empty.vmem",
                      VMI_INIT_DOMAINNAME | VMI_INIT_EVENTS, NULL,
                      VMI_CONFIG_STRING, (void *)config, &error);
    /* error 7 = NO_CONFIG, 8 = NO_CONFIG_ENTRY -> parser rejected config;
       error 5 = OS init failed after successful parse */
    printf("%-12s error=%d %s\n", label, error,
           (error == VMI_INIT_ERROR_NO_CONFIG ||
            error == VMI_INIT_ERROR_NO_CONFIG_ENTRY) ? "PARSE-REJECTED" : "PARSE-OK");
    if (vmi)
        vmi_destroy(vmi);
}

int main(void)
{
    try_config("good",
               "g { ostype = \"NetBSD\"; netbsd_pid = 0x70; "
               "netbsd_name = 0x1; netbsd_vmspace = 0x2; "
               "netbsd_pmap = 0x3; netbsd_pgd = 0x4; }");
    try_config("bad-token",
               "g { ostype = \"NetBSD\"; bogus_key = 0x70; }");
    try_config("unknown-os",
               "g { ostype = \"Plan9\"; }");
    return 0;
}

