#include <stdio.h>
#include <glib.h>
#include "config/config_parser.h"

extern FILE *yyin;

int main(int argc, char **argv)
{
    if (argc < 3)
        return 2;

    yyin = fopen(argv[1], "r");
    if (!yyin) {
        perror("fopen");
        return 2;
    }

    int rc = vmi_parse_config(argv[2]);
    if (rc != 0) {
        printf("PARSE-FAILED rc=%d\n", rc);
        return 1;
    }

    GHashTable *cfg = vmi_get_config();
    if (!cfg) {
        printf("NO-ENTRY\n");
        return 1;
    }

    GHashTableIter iter;
    gpointer key, value;
    g_hash_table_iter_init(&iter, cfg);
    while (g_hash_table_iter_next(&iter, &key, &value)) {
        printf("%s = %llu\n", (char *)key,
               (unsigned long long)*(uint64_t *)value);
    }
    printf("PARSE-OK\n");
    return 0;
}

